OPENQASM 2.0;                 // Specify OpenQASM version [^1]
include "qelib1.inc";         // Include the standard quantum library [^2]

// Quantum register with a single qubit and classical register with two bits
qreg qubit[1];                // Single-qubit quantum register [^4]
creg bits[2];                 // Two-bit classical register [^3]

// Prepare qubit in a superposition state
h qubit[0];                   // Apply Hadamard gate to the qubit [^5]

// Measure the qubit and store the result in the first bit of classical register
measure qubit[0] -> bits[0];  // Measurement operation [^6]

// The second bit remains in its initial state (0)
